css:
.demo {
  display: grid;
  gap: 16px;
  justify-items: start;
  padding: 16px;
  font-family: system-ui, sans-serif;
}

.tags {
  display: flex;
  gap: 8px;
}

.tag {
  padding: 4px 12px;
  border-radius: 999px;
  background-color: #fed7aa;
  font-size: 0.875rem;
}

.avatar {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background-color: #f97316;
  color: #ffffff;
  font-weight: 600;
}

.card {
  width: 260px;
  border: 1px solid #d4d4d8;
  border-radius: 12px;
  overflow: hidden;
}

.card-head {
  padding: 10px 14px;
  background-color: #f97316;
  color: #ffffff;
  font-weight: 600;
}

.card-body {
  margin: 0;
  padding: 12px 14px;
}
